import { hash, verify } from "@node-rs/argon2";

export {
  isStrongPassword,
  passwordProblems,
  PASSWORD_MAX_LENGTH,
  PASSWORD_MIN_LENGTH,
} from "./password-policy";

/**
 * Argon2id password hashing.
 *
 * Parameters: m=32 MiB, t=3, p=1, 32-byte random salt generated by the library.
 * The algorithm is intentionally not passed: @node-rs/argon2 defaults to
 * Argon2id (and `verify` reads it back from the stored hash), while the
 * exported `Algorithm` enum is an ambient const enum that cannot be referenced
 * under `isolatedModules`.
 *
 * This satisfies current OWASP password storage guidance while staying inside
 * the CPU budget of a Vercel serverless function invocation.
 */
const ARGON_OPTIONS = {
  memoryCost: 32768,
  timeCost: 3,
  parallelism: 1,
} as const;

const MAX_PASSWORD_LENGTH = 1024;

export async function hashPassword(password: string): Promise<string> {
  if (!password) throw new Error("password must not be empty");
  if (password.length > MAX_PASSWORD_LENGTH) {
    throw new Error(`password must be at most ${MAX_PASSWORD_LENGTH} characters`);
  }
  return hash(password, ARGON_OPTIONS);
}

/**
 * Constant-time verification. Returns false instead of throwing for malformed
 * hashes so callers cannot distinguish "bad password" from "corrupt record".
 */
export async function verifyPassword(storedHash: string, password: string): Promise<boolean> {
  if (!storedHash || !password || password.length > MAX_PASSWORD_LENGTH) return false;
  try {
    return await verify(storedHash, password, ARGON_OPTIONS);
  } catch {
    return false;
  }
}

export function needsRehash(storedHash: string): boolean {
  if (!storedHash.startsWith("$argon2id$")) return true;
  const match = storedHash.match(/\$m=(\d+),t=(\d+),p=(\d+)/);
  if (!match) return true;
  return Number(match[1]) < ARGON_OPTIONS.memoryCost;
}
